SELECT CASE WHEN YEAR(p.launch_date) < 2024 THEN 'before_2024' WHEN YEAR(p.launch_date) = 2024 THEN '2024' ELSE 'after_2024' END AS launch_cohort, MAX(oi.quantity) - MIN(oi.quantity) AS quantity_range, MAX(oi.unit_price) - MIN(oi.unit_price) AS unit_price_range FROM order_items oi JOIN products p ON p.id = oi.product_id GROUP BY CASE WHEN YEAR(p.launch_date) < 2024 THEN 'before_2024' WHEN YEAR(p.launch_date) = 2024 THEN '2024' ELSE 'after_2024' END ORDER BY unit_price_range
